def multiply_matrices(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
    m, k, n = len(a), len(a[0]), len(b[0])
    res = [[0] * n for _ in range(m)]
    for i in range(m):
        for j in range(n):
            res[i][j] = sum(a[i][p] * b[p][j] for p in range(k))
    return res
